import{_ as s,o as t,c as n,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"The Sound of Simulation: Learning Multimodal Sim-to-Real Robot Policies with Generative Audio","description":"","frontmatter":{"title":"The Sound of Simulation: Learning Multimodal Sim-to-Real Robot Policies with Generative Audio","arxiv":"2507.02864","date":"2025-07-03","authors":"Renhao Wang, Haoran Geng, Tingle Li, Feishi Wang, Gopala Anumanchipalli, Trevor Darrell, Boyi Li, Pieter Abbeel, Jitendra Malik, Alexei A. Efros","categories":"cs.RO, cs.CV","topics":"多模态仿真, sim-to-real, 生成式音频","outline":[2,2]},"headers":[],"relativePath":"papers/2507.02864.md","filePath":"papers/2507.02864.md","lastUpdated":null}'),l={name:"papers/2507.02864.md"};function o(r,a,i,p,c,m){return t(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="the-sound-of-simulation-learning-multimodal-sim-to-real-robot-policies-with-generative-audio" tabindex="-1">The Sound of Simulation: Learning Multimodal Sim-to-Real Robot Policies with Generative Audio <a class="header-anchor" href="#the-sound-of-simulation-learning-multimodal-sim-to-real-robot-policies-with-generative-audio" aria-label="Permalink to &quot;The Sound of Simulation: Learning Multimodal Sim-to-Real Robot Policies with Generative Audio&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2507.02864" target="_blank" rel="noreferrer">2507.02864</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-07-03</td></tr><tr><td><strong>作者</strong></td><td>Renhao Wang, Haoran Geng, Tingle Li, Feishi Wang, Gopala Anumanchipalli, Trevor Darrell, Boyi Li, Pieter Abbeel, Jitendra Malik, Alexei A. Efros</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把视频→音频生成模型挂在物理仿真器旁边合成&quot;听得见&quot;的仿真轨迹，让倒水策略不用一条真机数据就零样本迁移到真实世界。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文按 arXiv v2（2025-09-22 修订）全文撰写，v1 提交于 2025-07-03。comments 标注 CoRL 2025。方法名在正文中一律小写写作 multigen，本文统一写作 MultiGen。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>倒水这件事很难只靠看完成。液体透明、被容器遮挡、杯口反光，视觉给出的液面高度估计经常是错的；而人做这件事时明显在听——水柱撞击杯底的声音随着液面上升而升高音调，这是判断&quot;倒够了没有&quot;的主要信号。要让策略用上这条信号，就得有配对的视听机器人数据，而这类数据需要同步标定的麦克风与相机、专门的硬件与大量人工遥操作，规模上不去。论文点出的现实困境是：视觉能靠仿真扩规模，声音不能——声波传播依赖复杂的波动方程与材料参数，高保真音频仿真既贵又不实用，于是 sim-to-real 迁移至今基本只在纯视觉任务上成功。</p><p>这个缺口重要，是因为它不是倒水一个任务的问题。凡是接触丰富、有遮挡、靠非视觉反馈闭环的任务（插拔、摩擦、容器内取物），都卡在同一处：仿真器造得出几何和动力学，造不出&quot;听感&quot;和&quot;触感&quot;。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>已有三条路线。第一条是物理法声音仿真，用数值波传播或射线追踪求解，能做到高保真，但要给出详细材料属性且计算昂贵，无法支撑大规模策略训练。第二条是真机多模态数据采集：ManiWav 一类工作已经证明视听策略在接触丰富任务上有效，但它们依赖遥操作数据集，规模受限，且论文指出这类方法在做数据增强时只是把 ESC-50 环境噪声与机器人电机声按 50% 概率叠加到原音上——增加的是干扰而不是新的物理情形。第三条是把生成模型塞进仿真器：LucidSim 用文生图替代视觉域随机化，Gen2Sim 生成 3D 资产与 URDF，Eureka 用 LLM 写奖励函数。论文明确把自己与这一支划开：前人用生成模型增强已有的能力，本文用它引入仿真器根本不具备的一整个感知通道。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点是一个已被验证的事实：视频到音频的生成模型（MMAudio 一类）已经能给无声视频配出同步的、物理上说得通的声音。同时另一个事实是：现代仿真器能渲染出足够真实的 RGB。把这两件事并排放，一个直接的想法是——仿真器渲染视频，生成模型给这段视频配音，于是仿真轨迹就同时有了视觉、动作和声音。</p><p>接下来必然撞上两个问题。一是通用视频到音频模型没见过多少倒水，它的预训练语料以嘈杂的 Foley 音为主，倒水是长尾事件，音高随液面变化、黏度依赖、起止瞬态这些关键声学线索学得很差。解法是拿真实倒水视频去微调。二是微调完的模型见的是自然视频，喂给它仿真渲染帧会掉性能。解法要么把仿真渲染做得更像真的，要么给模型一个跨域稳定的条件——作者选了后者，用 SAMv2 把任务相关物体（杯、马克杯、水、果汁）分割出来，把掩码作为额外条件注入，让模型盯住语义上有意义的区域而不是像素风格。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>难仿真的模态不必用物理去仿真，可以用一个在真实数据上训练过的生成模型，条件在仿真器已经能给出的量（渲染视频）上，把它&quot;配&quot;出来。物理引擎负责保证事件在时间上和空间上是对的，生成模型负责保证这个事件听起来是对的；两者串起来，仿真里就凭空多出一条传感通道，而这条通道的真实性来自互联网视频而非声学求解器。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以一次仿真倒水为例，流水线是这样跑的。</p><ul><li><strong>场景搭建</strong>：在 RoboVerse 里粗略复刻真实工位，相机位置只做近似对齐，不要求精确外参。随后对液体属性（密度、黏度、颜色、透明度、表面摩擦）、相机位姿扰动、光照强度与阴影、背景与桌面纹理做结构化域随机化，并随机缩放杯口与瓶高以扩大几何多样性。</li><li><strong>生成轨迹</strong>：倒水容器预先注满 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.0833em;"></span><span class="mord">70%</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">5%</span></span></span></span>，抓取点在容器中心 5% 偏移内采样；机器人把容器移到接收容器上方，倾倒高度在预设范围内随机；从&quot;四分之一 / 一半 / 四分之三 / 全倒&quot;中采一个目标量，据初始液位解析算出倾角；倒完回正，回合结束。轨迹用运动规划生成。</li><li><strong>配音</strong>：仿真开两个线程并行。第一个线程执行轨迹，记录 RGB、本体感知与动作；关键是<strong>额外架一台正对接收容器的虚拟相机</strong>，因为与真实工位对齐的那台相机常被严重遮挡，且视角与微调语料不匹配。第二个线程拿这路虚拟视频喂给微调过的 MMAudio，生成整段音频。</li><li><strong>微调音频模型</strong>：语料来自 EPIC-Kitchens 第一人称烹饪视频与自建 YouTube 爬取，覆盖水、咖啡、汽水、汤与玻璃、塑料、陶瓷容器，片段 5–60 秒，共 1031 条。在 MMAudio 的 transformer 骨干里新增一组投影与交叉注意力参数，接收 SAMv2 掩码条件。</li><li><strong>训练与部署</strong>：在生成的视听轨迹上从零训练 Diffusion Policy，RGB 用 CLIP 预训练 ViT-B/16 编码，音频用 Audio Spectrogram Transformer 编码（192 kHz 24-bit 降采样到 16 kHz 16-bit，FFT 窗 400、hop 160、64 个 mel 滤波器）。真机是 Kinova Gen3 + Robotiq 2F-85，单目 Logitech BRIO 自我中心视角，末端夹持 MAONO 全向 USB 领夹麦克风，10 Hz 输出 6-DoF 笛卡尔增量，MoveIt 逆解成 7 自由度关节指令。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>全文只有一个形式化定义，即评测指标归一化平均绝对误差：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">NMAE</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.113em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord cjk_fallback">目标量</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="minner"><span class="mopen delimcenter" style="top:0em;">∣</span><span class="mord text"><span class="mord cjk_fallback">实际倒出量</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord text"><span class="mord cjk_fallback">目标量</span></span><span class="mclose delimcenter" style="top:0em;">∣</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>目标量由倒水容器的已知初始体积与语言指令共同确定（例如&quot;倒一半&quot;）。用相对误差而非绝对体积，是为了让四条指令与不同容器之间可比——绝对误差在&quot;倒全部&quot;上天然更大。需要注意这个指标的量纲含义：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">NMAE</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.4</span></span></span></span> 意味着倒出量平均偏离目标 40%，这不是一个接近饱和的数字。音频生成侧用的对数谱距离（LSD，衡量多样性）与信号失真比（SDR，衡量保真度）在文中未给公式。除此之外，MMAudio 的条件流匹配训练目标沿用原文，本文未做新的推导。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：仿真里学到的视听策略能不能零样本迁移？</strong> 设计上，作者搭了一个 8 条件的真机基准，覆盖不透明容器（水-白杯-红杯、咖啡-金属保温杯-纸杯、清酒-酒壶-酒杯、水-金属保温杯-金属马克杯）与透明容器（水-白杯-塑料杯、果汁-塑料瓶-塑料杯、汽水-金属罐-塑料杯、果汁-塑料瓶-玻璃马克杯）。每条件三组随机初始位置 × 四条语言指令 = 12 次评测，全部零样本。结论是纯视觉版 NMAE 在 0.43–0.68，视听版在 0.33–0.44，音频平均降低 NMAE 23.3%；不透明容器上降幅 29.4%，透明容器上仅 16.2%，与&quot;视觉受限时听觉更重要&quot;的直觉一致。</p><p>这里有一处需要按表核对的数字：正文写&quot;平均 NMAE 0.46&quot;，但表 1 里视听版八个条件的算术平均是约 0.40，纯视觉版是约 0.52，0.46 恰好是<strong>两个变体一起平均</strong>的结果。引用时应以 0.40 作为本文策略的平均误差。相对降幅按表 1 复算约为 21.9%（不透明 28.9%、透明 14.9%），与正文的 23.3/29.4/16.2 略有出入，差异量级与表中两位小数的取整一致，可视为一致。</p><p><strong>问题二：生成的音频到底比传统增强好在哪？</strong> 作者采了 10 条真机倒水演示作参照，一边按 ManiWav 协议做加噪增强生成 1000 条样本，一边用微调后的生成模型（条件在这 10 条演示的 RGB 与 SAMv2 掩码上）生成 1000 条。用最小 LSD 衡量多样性、SDR 衡量保真度，结论是生成音频同时更分散且失真更低，并且用生成数据训练的策略随轨迹数增长的 scaling 更好。<strong>这一组只有图 4，无数值表</strong>，本文不复述具体分数。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：仿真能给视觉却给不了声音，导致多模态 sim-to-real 长期无法落地。MultiGen 让物理引擎与视频到音频生成模型并行运行，用仿真渲染的正面虚拟视角作条件合成音频，凑齐视听动三元组。生成模型先在 EPIC-Kitchens 与 YouTube 的 1031 条真实倒水片段上微调，再用 SAMv2 掩码条件缓解仿真到真实的视觉域差。在 8 条件真机倒水基准上零样本部署，加音频使 NMAE 平均降低约 23%，不透明容器上降幅约为透明容器的两倍。整条链路不使用任何真机机器人动作或传感数据。</p><p><strong>三句话版</strong>：难以仿真的感知通道可以交给在真实数据上训练的生成模型，条件在仿真器已有的渲染视频上。作者在倒水任务上做了实例化，零样本迁移成立且音频确实带来收益。收益集中在视觉被遮挡的不透明容器上。</p><p><strong>一句话版</strong>：用生成模型给仿真配音，把多模态 sim-to-real 从&quot;仿真不出来&quot;变成&quot;生成出来&quot;。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的一条是：<strong>生成模型合成的声音与真机麦克风采到的声音处于同一分布</strong>。这个假设有三重具体压力。其一，生成条件是一台&quot;正对接收容器&quot;的虚拟相机视角，而部署时的麦克风装在末端执行器上，随机械臂一起运动——生成端的&quot;听点&quot;与部署端的听点在几何上不是一回事，机械臂自噪声、气流噪声、麦克风相对声源的移动全部不在生成分布里。其二，微调语料是人手倒水的第一人称视频，人的倒水速度曲线与运动规划器生成的机器人倾角轨迹不同，音高变化率的统计可能系统性偏移。其三，生成模型只被要求&quot;听起来像倒水&quot;，没有任何机制保证音高与仿真中的真实液位一一对应；如果它学到的是&quot;倒水声的先验样貌&quot;而非&quot;这一次的液位曲线&quot;，策略学到的就是一个与目标量无关的伴奏。</p><p>论文为此提供的证据是间接的：SDR 高于加噪增强，且视听策略确实优于纯视觉策略。缺的是直接证据——没有把生成音频的音高轨迹与仿真真实液位曲线做回归，也没有&quot;用真实录音替换生成音频&quot;的对照来给出上界。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做且不需要复现整套系统的版本：拿 10–20 条真机倒水录像（手持即可，不需要机器人），标注每一帧的真实液位（水位线像素高度足够）。用公开的 MMAudio 权重，分别在（a）不微调、（b）在几十条倒水视频上微调、（c）微调并加分割掩码条件三种设置下，给同一批<strong>仿真渲染视频</strong>配音，然后从生成音频提取基频轨迹（YIN 或 CREPE），与仿真器输出的真实液位曲线做逐帧相关。支持论文的结果是：相关系数随 (a)→(b)→(c) 单调上升且 (c) 显著高于 0；反驳的结果是三种设置的相关都接近 0，说明音频只是风格正确的伴奏，此时策略的增益必须另找解释。整个实验不需要机器人，只需一张显卡。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是提出一个替代解释：<strong>音频通道带来的可能不是液位信息，而是一个&quot;倒水正在发生 / 已经停止&quot;的二值门控</strong>。这个假设同样能解释论文的全部现象——不透明容器上视觉判不出何时开始出流，所以门控信号价值更高（29.4%）；透明容器上视觉已能看到水柱，门控冗余（16.2%）。要判决，只需两个负控制：把生成音频替换成&quot;检测到出流时播放固定白噪声、否则静音&quot;的合成方波，以及把音频在时间上整体平移 0.3 秒（保留能量包络，破坏音高—液位对应）。若二值门控版几乎复现完整版性能，则&quot;音频提供细粒度液位估计&quot;的说法不成立。</p><p>第二条攻击针对绝对水平。策略的平均 NMAE 约 0.40，意味着让它&quot;倒一半&quot;时平均倒出量偏离目标 40%。一个不看不听、只按初始体积解析算倾角并开环执行的脚本基线（正是仿真里生成演示的那个规划器）在真机上能拿到多少 NMAE？论文没有报告。如果脚本基线也在 0.5 附近，那么&quot;零样本迁移成功&quot;的边际就非常薄。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：MultiGen 的生成模型是单向、离线、开环的——仿真跑完再配音，音频不参与仿真状态，也不受物理约束校验。这决定了声音永远只能是仿真状态的&quot;渲染结果&quot;，无法反过来暴露仿真的错误。</p><p><strong>新的 framing</strong>：把生成式感知通道当作<strong>可微的软传感器</strong>，与物理仿真做闭环耦合，并让它承担一致性检验的职责。具体地说，训练一个逆向读数器 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span>：从生成音频回归出液位、流速、容器材质等仿真器已知的隐变量；把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∥</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mopen">(</span><span class="mord text"><span class="mord">audio</span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">sim state</span></span><span class="mord">∥</span></span></span></span> 作为生成过程的引导项（分类器引导或直接微调），这样生成的音频不只是&quot;像&quot;，而是被强制携带该次 rollout 的物理信息。同一读数器还可以在真机上跑：如果它在真实录音上的读数与视觉估计一致而在生成音频上不一致，就定位到了生成侧的域差。</p><p><strong>可借鉴的相邻领域</strong>：可微渲染中的&quot;分析-合成&quot;范式，以及语音领域的声码器一致性损失（把生成波形送回声学特征提取器并要求还原条件）。两者都提供了成熟的&quot;生成—反演—对齐&quot;工具链。</p><p><strong>第一个实验</strong>：在倒水任务上只训练读数器 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span>（输入音频、输出液位），先验证它在真实录音上的精度；然后把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 接入生成引导，比较有无引导时策略的 NMAE 与 §10 中的音高—液位相关系数。若引导同时提升两者，这条路线成立；若相关系数升而 NMAE 不动，则说明策略本来就没在用细粒度音频信息，问题回到 §11。</p>',42)])])}const d=s(l,[["render",o]]);export{h as __pageData,d as default};
